    "res_ds_karin.1": { en: "Do you know where the water of our oasis comes from?", t: [["Weißt", "", "know", "wissen"], ["du", "", "you"], [",", "", ""], ["woher", "", "where from"], ["das", "", "the", "der"], ["Wasser", "", "water"], ["unserer", "", "our", "unser"], ["Oase", "", "oasis"], ["kommt", "", "comes", "kommen"], ["?", "", ""]] },
    "res_ds_karin.2": { en: "From deep under the ground! It's rain from many thousands of years ago. Here it comes up to the surface.", t: [["Aus", "", "from", "aus"], ["der", "", "the"], ["Tiefe", "", "depth"], ["unter", "", "under"], ["der", "", "the"], ["Erde", "", "ground"], ["!", "", ""], ["Es", "", "it", "es"], ["ist", "", "is", "sein"], ["Regen", "", "rain"], ["von", "", "from"], ["vor", "", "ago"], ["vielen", "", "many", "viel"], ["tausend", "", "thousand"], ["Jahren", "", "years", "Jahr"], [".", "", ""], ["Hier", "", "here", "hier"], ["kommt", "", "comes", "kommen"], ["es", "", "it"], ["nach", "", "to"], ["oben", "", "the top"], [".", "", ""]] },
    "res_ds_karin.3": { en: "That's why we never waste water.", t: [["Darum", "", "that's why", "darum"], ["verschwenden", "", "waste"], ["wir", "", "we"], ["nie", "", "never"], ["Wasser", "", "water"], [".", "", ""]] },
