    "res_ds_rolf.2": { en: "When sand slides down a big dune, it hums like a deep drum. You can hear it far away.", t: [["Wenn", "", "when", "wenn"], ["Sand", "", "sand"], ["eine", "", "a", "ein"], ["große", "", "big", "groß"], ["Düne", "", "dune"], ["hinunterrutscht", "", "slides down", "hinunterrutschen"], [",", "", ""], ["brummt", "", "hums", "brummen"], ["sie", "", "it"], ["wie", "", "like"], ["eine", "", "a", "ein"], ["tiefe", "", "deep", "tief"], ["Trommel", "", "drum"], [".", "", ""], ["Man", "", "one", "man"], ["hört", "", "hears", "hören"], ["es", "", "it"], ["weit", "", "far"], ["weg", "", "away"], [".", "", ""]] },
    "res_ds_rolf.3": { en: "Listen carefully when you walk through the dunes.", t: [["Hör", "", "listen", "hören"], ["gut", "", "carefully"], ["zu", "", "(zuhören: to listen)", "zuhören"], [",", "", ""], ["wenn", "", "when"], ["du", "", "you"], ["durch", "", "through"], ["die", "", "the", "der"], ["Dünen", "", "dunes", "Düne"], ["gehst", "", "walk", "gehen"], [".", "", ""]] },
    "res_ds_renate.1": { en: "In the desert it rarely rains. Sometimes not for years.", t: [["In", "", "in", "in"], ["der", "", "the"], ["Wüste", "", "desert"], ["regnet", "", "rains", "regnen"], ["es", "", "it"], ["selten", "", "rarely"], [".", "", ""], ["Manchmal", "", "sometimes", "manchmal"], ["jahrelang", "", "for years"], ["nicht", "", "not"], [".", "", ""]] },
